import app from 'flarum/forum/app';
import Icon from 'flarum/common/components/Icon';
import Link from 'flarum/common/components/Link';
import { t, avatar } from '../util';

/*
 * Pieces both heroes draw, in Marquee's hero language: always dark, the
 * artwork blown up behind a darkening gradient, a shadowed poster, pills,
 * a dotted meta line, score rings, a round-avatar people strip and
 * translucent buttons. Called as functions, never used as tags.
 */

export function backdrop(image) {
  return image ? m("div", {
    className: "EarshotHero-backdrop",
    style: {
      backgroundImage: `url("${encodeURI(image)}")`
    }
  }) : m("div", {
    className: "EarshotHero-backdrop"
  });
}
export function meta(parts) {
  const list = parts.filter(Boolean);
  return list.length ? m("ul", {
    className: "EarshotHero-meta"
  }, list.map(part => m("li", null, part))) : null;
}

/** A Marquee score ring: value in the middle, the ring filled to `percent`. */
export function ring(value, label, percent, kind) {
  return m("div", {
    className: `EarshotHero-score EarshotHero-score--${kind}`
  }, m("span", {
    className: "EarshotHero-ring",
    style: {
      '--v': Math.max(0, Math.min(100, percent))
    }
  }, m("b", null, value)), m("span", {
    className: "EarshotHero-scoreLabel"
  }, label));
}
export function people(title, users, role) {
  if (!users || !users.length) return null;
  return m("div", {
    className: "EarshotHero-people"
  }, m("h2", {
    className: "EarshotHero-sectionTitle"
  }, title), m("ul", null, users.map(u => m("li", null, m(Link, {
    href: app.route('user', {
      username: u.slug
    })
  }, avatar(u, 'EarshotHero-avatar'), m("b", null, u.displayName || u.username), m("span", null, role))))));
}
const LINK_ICONS = {
  apple: 'fas fa-podcast',
  spotify: 'fab fa-spotify',
  youtube: 'fab fa-youtube',
  pocketcasts: 'fas fa-headphones',
  overcast: 'fas fa-tower-broadcast'
};

/** Subscribe buttons: each service the show is on, then its RSS feed. */
export function subscribeButtons(show) {
  const links = show.links || {};
  return [...Object.keys(LINK_ICONS).filter(k => links[k]).map(k => m("a", {
    className: "Button EarshotHero-button",
    href: links[k],
    target: "_blank",
    rel: "noopener noreferrer"
  }, m(Icon, {
    name: LINK_ICONS[k]
  }), m("span", {
    className: "Button-label"
  }, t(`links.${k}`)))), show.feedUrl ? m("a", {
    className: "Button EarshotHero-button",
    href: show.feedUrl,
    target: "_blank",
    rel: "noopener noreferrer",
    title: t('links.rss_help')
  }, m(Icon, {
    name: "fas fa-rss"
  }), m("span", {
    className: "Button-label"
  }, t('links.rss'))) : null];
}
flarum.reg.add('ernestdefoe-earshot', 'forum/components/heroBits', { backdrop: backdrop,meta: meta,ring: ring,people: people,subscribeButtons: subscribeButtons, });